from fastapi import APIRouter
router = APIRouter()

from fastapi import Response
from utils.css import ThemeEngine
theme = ThemeEngine(palette_mode='obsidian')

@router.get('/static/theme.css')
async def get_dynamic_stylesheet():
    # Serves CSS dynamically generated by Python.
    # Changes to theme_engine.py reflect instantly on reload.
    css_content = theme.render_stylesheet()
    return Response(content=css_content, media_type='text/css')